MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    y = [n + 1] + [0] * (n + 1)
    for i in range(n):
        y[data[2 * i + 1]] = data[2 * i + 2]

    # The canonical chosen balls are all isolated remaining balls.
    dp = [0] * (n + 2)
    dp[0] = 1
    for b in range(1, n + 2):
        low = y[b]
        total = 0
        for a in range(b):
            high = y[a]
            if high <= low or not dp[a]:
                continue
            candidates = []
            minimum = n + 2
            for k in range(a + 1, b):
                v = y[k]
                if not low < v < high:
                    continue
                # Isolated points must be prefix minima and suffix maxima.
                if v < minimum:
                    candidates.append(v)
                    minimum = v
                else:
                    while candidates and candidates[-1] < v:
                        candidates.pop()
            if not candidates:
                total += dp[a]
        dp[b] = total % MOD
    print(dp[-1])

