import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]

    # ban[l][x]: smallest right endpoint of a condition at x
    # whose left endpoint is at least l.
    ban = [[n + 1] * (n + 2) for _ in range(n + 2)]
    for i in range(2, len(data), 3):
        l, r, x = data[i], data[i + 1], data[i + 2]
        if l == r:
            print(0)
            return
        if r < ban[l][x]:
            ban[l][x] = r
    for l in range(n - 1, 0, -1):
        a, b = ban[l], ban[l + 1]
        for x in range(l, n + 1):
            if b[x] < a[x]:
                a[x] = b[x]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # Store both orientations of the interval DP for fast inner loops.
    # The DP value is the valid permutation count divided by length!.
    rows = [[0] * (n + 2) for _ in range(n + 2)]
    cols = [[0] * (n + 2) for _ in range(n + 2)]
    for l in range(1, n + 2):
        rows[l][l - 1] = 1
        cols[l - 1][l] = 1

    for l in range(n, 0, -1):
        row = rows[l]
        limits = ban[l]
        for r in range(l, n + 1):
            col = cols[r]
            total = 0
            for k in range(l, r + 1):
                if r < limits[k]:
                    total += row[k - 1] * col[k + 1]
            value = total * inv[r - l + 1] % MOD
            row[r] = value
            col[l] = value

    fact = 1
    for i in range(2, n + 1):
        fact = fact * i % MOD
    print(rows[1][n] * fact % MOD)


if __name__ == '__main__':
    main()

