import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1

    q = deque(i for i in range(n) if deg[i] == 0)
    # None represents the constant vector of ones.
    dp = [None] * n
    while q:
        v = q.popleft()
        p = a[v]
        cur = dp[v]
        dst = dp[p]
        if dst is None:
            if cur is None:
                dp[p] = list(range(1, m + 1))
            else:
                s = 0
                for j in range(m):
                    s = (s + cur[j]) % MOD
                    cur[j] = s
                dp[p] = cur
        elif cur is None:
            for j in range(m):
                dst[j] = dst[j] * (j + 1) % MOD
        else:
            s = 0
            for j in range(m):
                s = (s + cur[j]) % MOD
                dst[j] = dst[j] * s % MOD
        dp[v] = None
        deg[p] -= 1
        if deg[p] == 0:
            q.append(p)

    ans = 1
    for i in range(n):
        if deg[i] == 0:
            continue
        v = i
        acc = None
        while deg[v]:
            deg[v] = 0
            cur = dp[v]
            if cur is not None:
                if acc is None:
                    acc = cur
                else:
                    for j in range(m):
                        acc[j] = acc[j] * cur[j] % MOD
            v = a[v]
        ways = m if acc is None else sum(acc) % MOD
        ans = ans * ways % MOD
    print(ans)


if __name__ == '__main__':
    main()

