MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    spf = list(range(1001))
    for p in range(2, 32):
        if spf[p] == p:
            for x in range(p * p, 1001, p):
                if spf[x] == x:
                    spf[x] = p

    occurrences = {}
    for i, x in enumerate(a, 1):
        while x > 1:
            p = spf[x]
            v = 0
            while x % p == 0:
                x //= p
                v += 1
            occurrences.setdefault(p, []).append((i, v))

    answer = 1
    for p, edges in occurrences.items():
        # Heights are normalized so that the minimum seen so far is zero.
        dp = [1]
        limit = 0
        for j, (i, v) in enumerate(edges):
            next_i = edges[j + 1][0] if j + 1 < len(edges) else n
            length = next_i - i
            base = pow(p, length, MOD)
            weights = [1] * (limit + v + 1)
            for h in range(1, len(weights)):
                weights[h] = weights[h - 1] * base % MOD

            new_dp = [0] * (limit + v + 1)
            low_base = pow(p, i, MOD)
            low_weights = [1] * (v + 1)
            for h in range(1, v + 1):
                low_weights[h] = low_weights[h - 1] * low_base % MOD

            for h, value in enumerate(dp):
                if not value:
                    continue
                t = h + v
                new_dp[t] = (new_dp[t] + value * weights[t]) % MOD
                if h >= v:
                    t = h - v
                    new_dp[t] = (new_dp[t] + value * weights[t]) % MOD
                else:
                    # A new minimum raises all i preceding exponents.
                    new_dp[0] = (new_dp[0] + value * low_weights[v - h]) % MOD
            dp = new_dp
            limit += v

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)


