from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        ending = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, i))

        gains = [0] * len(conflictingPairs)
        first = second = 0
        owner = 0
        total = 0

        for right in range(1, n + 1):
            for left, i in ending[right]:
                if left > first:
                    second = first
                    first = left
                    owner = i
                elif left > second:
                    second = left

            total += right - first
            gains[owner] += first - second

        return total + max(gains)

