import sys


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    m = next(it)
    q = next(it)
    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    closed = [False] * m
    queries = []
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    INF = 10**18
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (u, v, w) in enumerate(edges):
        if not closed[e]:
            d[u][v] = d[v][u] = w

    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            a = di[k]
            if a == INF:
                continue
            for j in range(n):
                z = a + dk[j]
                if z < di[j]:
                    di[j] = z

    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            z = d[query[1]][query[2]]
            ans.append(str(z if z < INF else -1))
        else:
            u, v, w = edges[query[1]]
            if w >= d[u][v]:
                continue
            du = d[u]
            dv = d[v]
            # Only pairs on opposite sides can improve through this edge.
            # Snapshot distances before modifying the matrix.
            left = [(i, du[i] + w) for i in range(n) if du[i] + w < dv[i]]
            right = [(j, dv[j]) for j in range(n) if dv[j] + w < du[j]]
            for i, a in left:
                di = d[i]
                for j, b in right:
                    z = a + b
                    if z < di[j]:
                        di[j] = z
                        d[j][i] = z

    sys.stdout.write('\n'.join(reversed(ans)))


if __name__ == '__main__':
    main()

