import sys
from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    rows = []
    hi = 10**9 + 1
    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # S is at least as cost-effective as T.
        if p * b > q * a:
            a, p, b, q = b, q, a, p
        hi = min(hi, budget * a // p + 1)
        # This many T machines can be replaced by S machines
        # with identical capacity and no greater cost.
        rows.append((a, p, b, q, a // gcd(a, b)))

    lo = 0
    while hi - lo > 1:
        w = (hi + lo) // 2
        total = 0
        for a, p, b, q, limit in rows:
            best = ((w + a - 1) // a) * p
            for t in range(1, min(limit - 1, (w + b - 1) // b) + 1):
                remaining = w - t * b
                cost = t * q
                if remaining > 0:
                    cost += ((remaining + a - 1) // a) * p
                if cost < best:
                    best = cost
            total += best
            if total > budget:
                break
        if total <= budget:
            lo = w
        else:
            hi = w
    print(lo)


if __name__ == '__main__':
    main()

