class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        mod = 10**9 + 7
        length = len(s)

        # For x > 1, the first operation leaves popcount(x).
        steps = [0] * (length + 1)
        for x in range(2, length + 1):
            steps[x] = 1 + steps[x.bit_count()]
        good = [x for x in range(1, length + 1) if steps[x] < k]

        fact = [1] * (length + 1)
        for x in range(1, length + 1):
            fact[x] = fact[x - 1] * x % mod
        inv = [1] * (length + 1)
        inv[length] = pow(fact[length], mod - 2, mod)
        for x in range(length, 0, -1):
            inv[x - 1] = inv[x] * x % mod

        answer = 0
        prefix = 0
        for i, bit in enumerate(s):
            if bit == '1':
                # First differ from s here by placing a zero.
                remaining = length - i - 1
                subtotal = 0
                for ones in good:
                    t = ones - prefix
                    if t < 0:
                        continue
                    if t > remaining:
                        break
                    subtotal += fact[remaining] * inv[t] % mod * inv[remaining - t] % mod
                answer = (answer + subtotal) % mod
                prefix += 1
        return answer

