    for i in range(1, n):
        limit = upper[i - 1] + x
        if upper[i] > limit:
            upper[i] = limit
    for i in range(n - 2, -1, -1):
        limit = upper[i + 1] + x
        if upper[i] > limit:
            upper[i] = limit

    h = min(u + d for u, d in zip(upper, lower))
    print(total - n * h)


