from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        g = [[-1] * (m + 2)] + [[-1] + row + [-1] for row in grid] + [[-1] * (m + 2)]
        ans = 0
        for dr, dc in ((1, 1), (1, -1), (-1, -1), (-1, 1)):
            # Length of a valid straight segment ending at each cell.
            pref = [[0] * (m + 2) for _ in range(n + 2)]
            rows = range(1, n + 1) if dr == 1 else range(n, 0, -1)
            for i in rows:
                row, out, prev = g[i], pref[i], pref[i-dr]
                for j in range(1, m + 1):
                    v = row[j]
                    if v == 1:
                        out[j] = 1
                    else:
                        p = prev[j-dc]
                        if p and v == (2 if p & 1 else 0):
                            out[j] = p + 1

            # Clockwise rotation in matrix coordinates.
            tr, tc = dc, -dr
            suf = [[0] * (m + 2) for _ in range(n + 2)]
            rows = range(n, 0, -1) if tr == 1 else range(1, n + 1)
            for i in rows:
                row, nxt = g[i], g[i+tr]
                out, tail, head = suf[i], suf[i+tr], pref[i]
                for j in range(1, m + 1):
                    v = row[j]
                    length = 1
                    if nxt[j+tc] == (2 if v == 1 else 2-v):
                        length += tail[j+tc]
                    out[j] = length
                    if head[j]:
                        candidate = head[j] + length - 1
                        if candidate > ans:
                            ans = candidate
        return ans

