class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        facts = [1] * (n + 1)
        for i in range(1, n + 1):
            facts[i] = facts[i - 1] * i

        remaining = list(range(1, n + 1))
        odd, even = (n + 1) // 2, n // 2
        answer = []
        previous = -1

        for pos in range(n):
            m = n - pos - 1
            for i, value in enumerate(remaining):
                parity = value % 2
                if parity == previous:
                    continue
                o = odd - parity
                e = even - (1 - parity)
                need_o = (m + (1 - parity)) // 2
                if o != need_o:
                    continue
                count = facts[o] * facts[e]
                if k > count:
                    k -= count
                else:
                    answer.append(value)
                    remaining.pop(i)
                    odd, even = o, e
                    previous = parity
                    break
            else:
                return []
        return answer

