class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        # For a fixed target, each letter is either removed or kept
        # with exactly target occurrences.
        answer = len(s)
        for target in range(1, max(counts) + 1):
            deleted = kept = previous = 0
            for count in counts:
                next_deleted = min(deleted, kept) + count
                if count < target:
                    deficit = target - count
                    # Surplus occurrences of the preceding letter can
                    # fill this deficit with one operation instead of two.
                    next_kept = deficit + min(
                        deleted - min(previous, deficit),
                        kept - min(max(previous - target, 0), deficit)
                    )
                else:
                    next_kept = min(deleted, kept) + count - target
                deleted, kept = next_deleted, next_kept
                previous = count
            answer = min(answer, deleted, kept)
            if answer == 0:
                return 0
        return answer

