from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in adj[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # free: parent edge absent; attached: parent edge present.
        free = [0] * n
        attached = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if v == parent[u]:
                    continue
                base += free[v]
                gain = w + attached[v] - free[v]
                if gain > 0:
                    gains.append(gain)
            gains.sort(reverse=True)
            total = base + sum(gains[:k])
            free[u] = total
            attached[u] = total - (gains[k - 1] if len(gains) >= k else 0)

        return free[0]

