MOD = 998244353


def solve(h, w, grid):
    if any(row.count(b'A') & 1 for row in grid):
        return 0

    n = h + w
    parent = list(range(n))
    size = [1] * n
    diff = [0] * n
    components = n
    column_parity = [0] * w

    def find(x):
        value = 0
        while parent[x] != x:
            p = parent[x]
            diff[x] ^= diff[p]
            parent[x] = parent[p]
            value ^= diff[x]
            x = parent[x]
        return x, value

    for i, row in enumerate(grid):
        row_parity = 0
        for j, tile in enumerate(row):
            if tile == 65:
                row_parity ^= 1
                column_parity[j] ^= 1
            else:
                a, x = find(i)
                b, y = find(h + j)
                z = 1 ^ row_parity ^ column_parity[j] ^ x ^ y
                if a == b:
                    if z:
                        return 0
