    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        x, y, z = data[i] - 1, data[i + 1] - 1, data[i + 2]
        graph[x].append((y, z))
        graph[y].append((x, z))
    del data

    a = [-1] * n
    for root in range(n):
        if a[root] != -1:
            continue
        a[root] = 0
        if not graph[root]:
            continue

        component = [root]
        mask = 0
        for u in component:
            current = a[u]
            for v, z in graph[u]:
                expected = current ^ z
                if a[v] == -1:
                    a[v] = expected
                    mask |= expected
                    component.append(v)
                elif a[v] != expected:
                    print(-1)
                    return

        flip = 0
        size = len(component)
        values = [a[u] for u in component]
        for bit in range(mask.bit_length()):
            b = 1 << bit
            count = sum(1 for v in values if v & b)
            if count * 2 > size:
                flip |= b
        if flip:
            for u in component:
                a[u] ^= flip

    print(' '.join(map(str, a)))


