import sys
from math import isqrt


def main():
    n = int(sys.stdin.buffer.readline())
    limit = isqrt(n)

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * ((limit - start) // p + 1)
    primes = [p for p in range(2, limit + 1) if sieve[p]]

    # Nine divisors requires either p^8 or p^2*q^2, with distinct primes.
    answer = 0
    j = len(primes) - 1
    for i, p in enumerate(primes):
        while j > i and p * primes[j] > limit:
            j -= 1
        if j <= i:
            break
        answer += j - i

    for p in primes:
        if p ** 8 > n:
            break
        answer += 1

    print(answer)


if __name__ == '__main__':
    main()

