import sys
from itertools import permutations

def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    g = [[0] * n for _ in range(n)]
    for _ in range(next(it)):
        u, v = next(it) - 1, next(it) - 1
        g[u][v] = g[v][u] = 1
    h = [[0] * n for _ in range(n)]
    for _ in range(next(it)):
        u, v = next(it) - 1, next(it) - 1
        h[u][v] = h[v][u] = 1
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            pairs.append((i, j, h[i][j], next(it)))
    best = sum(a for i, j, e, a in pairs)
    for p in permutations(range(n)):
        cost = 0
        for i, j, e, a in pairs:
            if g[p[i]][p[j]] != e:
                cost += a
            if cost >= best:
                break
        if cost < best:
            best = cost
        if best == 0:
            break
    print(best)

if __name__ == '__main__':
    main()

