        u, v = next(it) - 1, next(it) - 1
        h[u][v] = h[v][u] = 1
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            pairs.append((i, j, h[i][j], next(it)))
    best = sum(a for i, j, e, a in pairs)
    for p in permutations(range(n)):
        cost = 0
        for i, j, e, a in pairs:
            if g[p[i]][p[j]] != e:
                cost += a
            if cost >= best:
                break
        if cost < best:
            best = cost
        if best == 0:
            break
    print(best)

