class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        dp = [1] * len(nums)
        targets = [1 << x for x in nums]
        masks = [(target << 1) - 1 for target in targets]
        done = [x == 0 for x in nums]
        remaining = sum(not flag for flag in done)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if done[i]:
                    continue
                dp[i] = (dp[i] | (dp[i] << value)) & masks[i]
                if dp[i] & targets[i]:
                    done[i] = True
                    remaining -= 1
            if remaining == 0:
                return k
        return -1

