import heapq
from math import isqrt

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        lower = limit // 10
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for p in range(2, isqrt(limit - 1) + 1):
            if prime[p]:
                start = p * p
                prime[start:limit:p] = b'\x00' * ((limit - 1 - start) // p + 1)
        if prime[n] or prime[m]:
            return -1

        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]
        powers = []
        place = 1
        while place < limit:
            powers.append(place)
            place *= 10

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost
            for place in powers:
                digit = value // place % 10
                if digit < 9:
                    nxt = value + place
                    new_cost = cost + nxt
                    if not prime[nxt] and new_cost < dist[nxt]:
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt < lower:
                        continue
                    new_cost = cost + nxt
                    if not prime[nxt] and new_cost < dist[nxt]:
                        dist[nxt] = new_cost
                        heapq.heappush(heap, (new_cost, nxt))
        return -1

