from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # Count splits where the first part is a prefix of the second.
        answer = sum(n - 2 * i for i in range(1, (n - 1) // 2 + 1)
                     if z[i] >= i)

        # For each second-part length, scan equal runs at that offset.
        for length in range(1, (n - 1) // 2 + 1):
            run = 0
            for i in range(n - length - 1, 0, -1):
                if nums[i] == nums[i + length]:
                    run += 1
                    if run >= length and (i > length or z[i] < i):
                        answer += 1
                else:
                    run = 0
        return answer

