from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        positions = [[] for _ in range(26)]
        for j, ch in enumerate(pattern, 1):
            positions[ord(ch) - 97].append(j)
        for row in positions:
            row.reverse()

        removable = [0] * len(source)
        for i in targetIndices:
            removable[i] = 1

        # Minimum number of removable positions used by each pattern prefix.
        dp = [len(source) + 1] * (m + 1)
        dp[0] = 0
        for i, ch in enumerate(source):
            cost = removable[i]
            for j in positions[ord(ch) - 97]:
                value = dp[j - 1] + cost
                if value < dp[j]:
                    dp[j] = value
        return len(targetIndices) - dp[m]

