        for i in range(n // 2):
            x, y, z = cost[i]
            u, v, w = cost[n - 1 - i]
            a, b, c, d, e, f = (
                x + v + min(c, d, e),
                x + w + min(c, e, f),
                y + u + min(a, b, f),
                y + w + min(a, e, f),
                z + u + min(a, b, d),
                z + v + min(b, c, d),
