class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            c = ord(ch) - 97
            mirror = stacks[25 - c]
            if mirror:
                score += i - mirror.pop()
            else:
                stacks[c].append(i)
