from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        low = bounds[0][0] - original[0]
        high = bounds[0][1] - original[0]
        for value, (u, v) in zip(original, bounds):
            low = max(low, u - value)
            high = min(high, v - value)
            if low > high:
                return 0
        return high - low + 1

